    def run(self, runner):
        """Execute every task by calling ``runner(name)`` once per task, in
        ``topo_order()`` (so every dependency runs before each task that
        depends on it), and return a status dict mapping each task name to one
        of ``'ok'``, ``'failed'`` or ``'skipped'``.

        Failure handling:
          * if ``runner(name)`` raises any exception, ``name`` is ``'failed'``
            (its return value, if any, is discarded);
          * every task that depends on ``name`` -- directly OR transitively --
            is ``'skipped'`` and its runner is never called;
          * tasks that depend on no failed task still run normally and are
            ``'ok'``.

        Execution continues through the whole topological order, so the
        returned map always covers every registered task. Never mutates
        ``_deps``.
        """
        # dependents[dep] lists tasks that directly depend on ``dep``; used to
        # mark failed tasks' dependents (and their dependents, transitively).
        dependents = {name: [] for name in self._deps}
        for name, deps in self._deps.items():
            for dep in deps:
                dependents[dep].append(name)

        status = {}
        blocked = set()  # depend (transitively) on a failed task -> 'skipped'
        for name in self.topo_order():
            if name in blocked:
                status[name] = "skipped"
                # Its dependents come later in topo order; block them too.
                blocked.update(dependents[name])
                continue
            try:
                runner(name)
            except Exception:
                status[name] = "failed"
                blocked.update(dependents[name])
            else:
