import random
from taskdag.scheduler import Scheduler

random.seed(7)
names = [chr(ord('a') + i) for i in range(9)]

def transitive_dependents(s, failed):
    """Tasks that depend (directly or transitively) on any failed task."""
    dependents = {n: [] for n in s._deps}
    for t, ds in s._deps.items():
        for d in ds:
            dependents[d].append(t)
    seen = set()
    stack = list(failed)
    while stack:
        cur = stack.pop()
        for dep in dependents[cur]:
            if dep not in seen:
                seen.add(dep)
                stack.append(dep)
    return seen

for trial in range(200):
    s = Scheduler()
    for _ in range(30):
        t, d = random.sample(names, 2)
        try:
            s.add_dependency(t, d)
        except ValueError:
            pass
    failers = set(random.sample(list(s._deps), random.randint(0, 5)))
    calls = []
    def runner(n):
        calls.append(n)
        if n in failers:
            raise ValueError("x")
    st = s.run(runner)

    # full coverage and valid statuses
    assert set(st) == set(s.tasks()), (set(st), set(s.tasks()))
    assert set(st.values()) <= {"ok", "failed", "skipped"}
    # failed exactly the runner-raisers
    assert {n for n, v in st.items() if v == "failed"} == failers
    # skipped = transitive dependents of any failure
    assert {n for n, v in st.items() if v == "skipped"} == transitive_dependents(s, failers)
    # ok = everyone else
    assert {n for n, v in st.items() if v == "ok"} == set(s.tasks()) - failers - transitive_dependents(s, failers)
    # runner invoked exactly once per ok/failed task, never for skipped
    assert len(calls) == len(set(calls)) == len(failers) + len(set(s.tasks()) - failers - transitive_dependents(s, failers))
    assert all(n not in calls for n, v in st.items() if v == "skipped")
    # calls respect a topological order (dep before dependent)
    pos = {n: i for i, n in enumerate(calls)}
    for t, ds in s._deps.items():
        if t in pos:
            for d in ds:
                assert pos[d] < pos[t]
